// 本段只保真实开工接触与实际result；不改变旧订单visitor或完成钱货凭据。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "task_shop_order_contact_state.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/tasks/task_source_projection.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status result(A& a,TaskShopOrderContactResult& r){a.field("result_id",r.result_id);a.field("request_actor_id",r.request_actor_id);a.field("request_sequence",r.request_sequence);return a.field("result_revision",r.result_revision);}
template<class A>Status start(A& a,TaskShopOrderContactStart& s){if(s.context.kind||s.context.encounter_id||s.context.input_error)return a.reject("UnsupportedTaskShopOrderContactContext");a.field("fact_id",s.fact_id);a.field("task_id",s.task_id);a.field("order_id",s.order_id);a.field("acceptance_fact_id",s.acceptance_fact_id);a.field("order_issue_fact_id",s.order_issue_fact_id);a.field("proprietor_actor_id",s.proprietor_actor_id);a.field("client_actor_id",s.client_actor_id);a.field("action_id",s.action_id);a.field("session_id",s.session_id);a.field("dialogue_id",s.dialogue_id);a.field("node_id",s.node_id);a.object("context",[&](auto& c){c.field("place_id",s.context.place_id);c.field("provider_actor_id",s.context.provider_actor_id);return c.field("role_id",s.context.role_id);});a.field("started_tick",s.started_tick);return a.optional("actual_result",s.actual_result,[](auto& c,auto& v){return result(c,v);});}
template<class A>Status state(A& a,TaskShopOrderContactState& s){a.field("version",s.version);if(s.version!=1)return a.reject("UnsupportedTaskShopOrderContactVersion");return dynamic_codec::table(a,"starts",s.starts,[](auto& c,auto& v){return start(c,v);});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("TaskShopOrderContactTooDeep");if(const auto* dict=v.as<BoundaryValue::Dict>()){if(dict->size()>CodecVisitor::max_items)return common_failure("TaskShopOrderContactTooLarge");std::set<StableId> keys;for(const auto& row:*dict){if(!keys.insert(row.first).second)return common_failure("DuplicateTaskShopOrderContactField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* array=v.as<BoundaryValue::Array>()){if(array->size()>CodecVisitor::max_items)return common_failure("TaskShopOrderContactTooLarge");for(const auto& row:*array){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Status emit_task_shop_order_contacts_fields(ProjectionWriter&w,const TaskShopOrderContactState&v){dynamic_projection::Archive a(w);return state(a,const_cast<TaskShopOrderContactState&>(v));}
BoundaryValue encode_task_shop_order_contacts(const TaskShopOrderContactState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_shop_order_contacts_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Outcome<TaskShopOrderContactState> decode_task_shop_order_contacts(const BoundaryValue& v){auto r=unique(v);if(!r.ok)return {false,{},r.error};TaskShopOrderContactState s;dynamic_codec::JsonArchive a(v);r=state(a,s);if(r.ok)r=a.finish();return r.ok?Outcome<TaskShopOrderContactState>{true,std::move(s),{}}:Outcome<TaskShopOrderContactState>{false,{},r.error};}
Status visit_task_shop_order_contacts_checkpoint(CodecVisitor& a,TaskShopOrderContactState& s){return state(a,s);}
Status emit_task_shop_order_contact_fact_fields(ProjectionWriter&w,const TaskShopOrderContactState&s,const StableId&id){dynamic_projection::Archive a(w);Status valid;if(const auto*row=s.starts.find(id)){valid=start(a,const_cast<TaskShopOrderContactStart&>(*row));}else return common_failure("TaskShopOrderContactSourceMissing",id);if(!valid.ok)return valid;return w.status();}
Outcome<BoundaryValue> encode_task_shop_order_contact_fact(const TaskShopOrderContactState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_task_shop_order_contact_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
